@Override public void createPaymentAccount(CreatePaymentAccountRequest req,StreamObserver<CreatePaymentAccountReply> responseObserver){
  try {
    PaymentAccount paymentAccount=coreApi.createPaymentAccount(req.getPaymentAccountForm());
    var reply=CreatePaymentAccountReply.newBuilder().setPaymentAccount(paymentAccount.toProtoMessage()).build();
    responseObserver.onNext(reply);
    responseObserver.onCompleted();
  } catch (RuntimeException e) {
    responseObserver.onError(e);
  }
}
